mapper.select:
SELECT id, ticket_code, initiation_id, warranty_id, title, description, category, priority, status, reporter_id, reporter_name, reporter_phone, assignee_id, assignee_name, accepted_at, started_at, resolved_at, closed_at, response_due_at, resolve_due_at, response_breached, resolve_breached, resolution_note, customer_score, customer_comment, file_ids, tenant_id, provider_trace_id, created_by, created_at, updated_by, updated_at, deleted FROM pmis_ops_ticket WHERE assignee_id = #{assigneeId} AND deleted = 0
AND status = #{status}
ORDER BY priority, created_at DESC
